import{_ as d,C as o,o as n,c as h,a5 as s,E as i,j as e,a as r}from"./chunks/framework.D_J2JZBr.js";const f=JSON.parse('{"title":"通用计算系统","description":"从 CS61C 和 RISC-V 进入处理器设计、定量建模、gem5 与开源 CPU 和 GPU 研究。","frontmatter":{"title":"通用计算系统","description":"从 CS61C 和 RISC-V 进入处理器设计、定量建模、gem5 与开源 CPU 和 GPU 研究。"},"headers":[],"relativePath":"learning/computer-architecture/general-purpose-systems.md","filePath":"learning/computer-architecture/general-purpose-systems.md","lastUpdated":1795531638000}'),l={name:"learning/computer-architecture/general-purpose-systems.md"};function c(u,t,p,g,b,C){const a=o("CourseTable");return n(),h("div",null,[t[0]||(t[0]=s('<h1 id="通用计算系统" tabindex="-1">通用计算系统 <a class="header-anchor" href="#通用计算系统" aria-label="Permalink to &quot;通用计算系统&quot;">​</a></h1><p>体系结构关心的不只是“处理器怎么接线”，还包括<strong>给定工作负载、面积、功耗与软件条件，为什么这样设计更合适</strong>。建议先理解指令集架构（Instruction Set Architecture，ISA）和微架构的区别，再学习流水线、存储层次与并行计算。硬件实现基础见 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字电路自学</a>。</p><h2 id="入门-连起程序与硬件" tabindex="-1">入门：连起程序与硬件 <a class="header-anchor" href="#入门-连起程序与硬件" aria-label="Permalink to &quot;入门：连起程序与硬件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://cs61c.org/" target="_blank" rel="noreferrer">UCB CS61C</a></td><td>公开课</td><td>入门—进阶</td><td>以 C、汇编、数据表示、处理器和存储层次连接软件与硬件</td></tr><tr><td>Patterson、Hennessy《Computer Organization and Design》</td><td>教材</td><td>入门—进阶</td><td>建议选择 RISC-V 版本；结合手算时序图与小程序学习</td></tr><tr><td><a href="https://course.ece.cmu.edu/~ece447/" target="_blank" rel="noreferrer">CMU 18-447</a></td><td>体系结构课程</td><td>进阶</td><td>通过流水线处理器和存储系统加深设计理解；各学期公开材料范围不同</td></tr><tr><td><a href="https://riscv.org/" target="_blank" rel="noreferrer">RISC-V International</a></td><td>官方规范入口</td><td>入门—深入</td><td>从所用整数 ISA、异常与特权机制查起，明确规范版本及扩展集合</td></tr></tbody></table><p>不要把 ISA 模拟器能执行程序，等同于硬件微架构正确。先明确指令语义，再检查取指、译码、执行、访存和提交之间的关系。对于流水线，必须解释数据冒险、控制冒险、旁路与停顿；对于 Cache，必须区分容量、行大小、相联度与缺失代价。</p><h2 id="进阶-学习定量方法" tabindex="-1">进阶：学习定量方法 <a class="header-anchor" href="#进阶-学习定量方法" aria-label="Permalink to &quot;进阶：学习定量方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://www2.eecs.berkeley.edu/Courses/CS152/" target="_blank" rel="noreferrer">UCB CS152</a></td><td>体系结构课程</td><td>进阶</td><td>扩展到现代处理器、存储系统与设计权衡，先检查所选学期先修要求</td></tr><tr><td>Hennessy、Patterson《计算机体系结构：量化研究方法》</td><td>教材</td><td>进阶—深入</td><td>不仅看结论，要复算工作负载、性能、能耗与成本之间的比较</td></tr><tr><td>Roofline（Williams、Waterman、Patterson，2009）</td><td>经典论文</td><td>进阶</td><td>用运算强度、带宽与峰值算力判断计算或访存瓶颈</td></tr><tr><td>Amdahl&#39;s Law in the Multicore Era（Hill、Marty，2008）</td><td>经典论文</td><td>进阶</td><td>在资源约束下讨论并行比例与多核配置，避免只追求核心数量</td></tr><tr><td>The Optimum Pipeline Depth for a Microprocessor（Hartstein、Puzak，2002）</td><td>经典论文</td><td>进阶</td><td>理解流水深度、锁存开销与停顿之间的权衡</td></tr><tr><td><a href="https://www.gem5.org/" target="_blank" rel="noreferrer">gem5</a></td><td>架构模拟平台</td><td>进阶—深入</td><td>可做 CPU、Cache 等设计空间探索，但必须说明模型、参数、预热与统计区间</td></tr></tbody></table><p>进一步可读乱序处理器机理模型、GPU 的 MWP/CWP 模型、LogCA，以及 DNN 加速器的 Timeloop / Accelergy。它们解决的问题和精度不同，不宜把模型预测直接写成芯片实测性能。阅读论文时记录“假设了什么、输入是什么、在哪些负载下验证、哪些机制没建模”。</p><h2 id="实践-选择一个开源系统读进去" tabindex="-1">实践：选择一个开源系统读进去 <a class="header-anchor" href="#实践-选择一个开源系统读进去" aria-label="Permalink to &quot;实践：选择一个开源系统读进去&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://github.com/chipsalliance/rocket-chip" target="_blank" rel="noreferrer">Rocket Chip</a></td><td>RISC-V SoC 生成器</td><td>进阶</td><td>适合研究参数化核、总线、Cache 与系统集成，先从默认配置读起</td></tr><tr><td><a href="https://github.com/riscv-boom/riscv-boom" target="_blank" rel="noreferrer">BOOM</a></td><td>乱序 RISC-V 核</td><td>深入</td><td>关注重命名、发射、重排序与恢复，宜先理解顺序流水线</td></tr><tr><td><a href="https://github.com/OpenXiangShan/XiangShan" target="_blank" rel="noreferrer">XiangShan</a></td><td>高性能 RISC-V 处理器</td><td>深入</td><td>面向复杂微架构与工程验证，不建议作为第一次 HDL 项目</td></tr><tr><td><a href="https://github.com/vortexgpgpu/vortex" target="_blank" rel="noreferrer">Vortex</a></td><td>开源 GPU 项目</td><td>进阶—深入</td><td>学习 SIMT、线程调度、访存及软硬件接口</td></tr><tr><td><a href="https://github.com/THU-DSP-LAB/ventus-gpgpu" target="_blank" rel="noreferrer">Ventus</a></td><td>开源 GPGPU 项目</td><td>进阶—深入</td><td>可用于研究 RISC-V 相关 GPU 栈；按项目支持范围准备编译与运行环境</td></tr></tbody></table><p>第一次实验不必修改大型处理器。可以固定一组小程序，用 gem5 改变 Cache 容量或相联度，记录执行时间、缺失率与访存统计；或者在已有教学核中加入一种旁路并比较 CPI。<strong>一次只改一个主要变量</strong>，同时记录输入、编译参数、模型配置和版本。IPC 更高不一定程序更快，频率与工作量也必须一致或明确交代。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',12)),i(a,{codes:"CS110,CS110P,CS210,EE219"}),t[1]||(t[1]=e("p",null,[r("先用 "),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cs110"},"CS110"),r(" 建立指令执行与性能分析基础，再按目标进入体系结构、GPU 或 AI 加速器。本文经典论文选择参考了维护者的往届定量建模笔记，阅读顺序是建议，不代表课程指定书目。")],-1)),t[2]||(t[2]=e("h2",{id:"参考与来源",tabindex:"-1"},[r("参考与来源 "),e("a",{class:"header-anchor",href:"#参考与来源","aria-label":'Permalink to "参考与来源"'},"​")],-1)),t[3]||(t[3]=e("ul",null,[e("li",null,[e("a",{href:"https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm",target:"_blank",rel:"noreferrer"},"上科大信息学院 2026–2027 学年开课计划"),r("。")]),e("li",null,"各课程、模拟器与开源核官方主页见上表；论文可按题名通过学校图书馆或作者主页检索。")],-1))])}const S=d(l,[["render",c]]);export{f as __pageData,S as default};
